function outer() {
  let count = 0;         // This variable is "closed over"

  function inner() {
    count++;             // inner accesses outer's variable
    console.log(count);
  }

  return inner;          // outer has returned, but count lives on
}

const counter = outer(); // outer() done, count not garbage collected
counter(); // 1
counter(); // 2 — count persists!

