function outer() {
  // When outer() is called, a stack frame is created.
  // 'secret' starts on the stack...
  let secret = 42;

  return function inner() {
    // inner closes over secret.
    // The engine detects this and MOVES secret to the HEAP.
    return secret;
  };
  // outer's stack frame is gone, but 'secret' lives on in the heap
}

const fn = outer();  // outer stack frame popped
fn();                // 42 — secret accessed from heap via closure

// When fn itself is GC'd, secret is finally freed from the heap.

function once(fn) {
  let called = false;   // closed over
  let result;           // closed over — cache first result

  return function(...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;      // always returns first call's result
  };
}

const initDB = once(function() {
  console.log('DB initialized!');
  return { connected: true };
});

initDB(); // "DB initialized!" → { connected: true }
initDB(); // (silent)          → { connected: true }
