function debounce(fn, delay) {
  let timer = null;    // closed over — persists between calls

  return function(...args) {
    // 'this' is the calling context
    clearTimeout(timer);        // cancel previous scheduled call

    timer = setTimeout(() => {
      fn.apply(this, args);     // calls fn with correct context + args
      timer = null;             // cleanup
    }, delay);
  };
}

// Usage:
