searchAPI('jav');    // cancelled
searchAPI('java');   // fires after 300ms — "Searching for: java"

// Closed over variables:
// timer — tracks the pending setTimeout ID across calls
// fn    — the original function (from outer scope)
// delay — the wait time (from outer scope)

function throttle(fn, limit) {
  let lastCall = 0;       // closed over — timestamp of last invocation

  return function(...args) {
    const now = Date.now();

    if (now - lastCall >= limit) {
      lastCall = now;
      return fn.apply(this, args);
    }
    // else: silently drop this call
  };
}

// Usage — scroll handler fires max once per 100ms:
